import pytest

# Replace `your_module` with the actual module name where zip_dicts is defined
from your_module import zip_dicts


def test_zip_dicts_happy_path_same_keys():
    result = zip_dicts(
        {"a": 1, "b": 2},
        {"a": 3, "b": 4},
    )

    assert result == {
        "a": [1, 3],
        "b": [2, 4],
    }


def test_zip_dicts_multiple_dicts():
    result = zip_dicts(
        {"a": 1},
        {"a": 2},
        {"a": 3},
    )

    assert result == {
        "a": [1, 2, 3],
    }


def test_zip_dicts_missing_keys_are_none():
    result = zip_dicts(
        {"a": 1, "b": 2},
        {"a": 3, "c": 4},
    )

    assert result == {
        "a": [1, 3],
        "b": [2, None],
        "c": [None, 4],
    }


def test_zip_dicts_preserves_none_values():
    result = zip_dicts(
        {"a": None},
        {"a": 1},
    )

    assert result == {
        "a": [None, 1],
    }


def test_zip_dicts_with_empty_dicts():
    result = zip_dicts({}, {})

    assert result == {}


def test_zip_dicts_with_some_empty_dicts():
    result = zip_dicts(
        {},
        {"a": 1},
        {},
    )

    assert result == {
        "a": [None, 1, None],
    }


def test_zip_dicts_with_no_arguments():
    result = zip_dicts()

    assert result == {}


def test_zip_dicts_with_mixed_key_types():
    result = zip_dicts(
        {"a": 1, 2: "two"},
        {"a": 3, 2: "second two"},
    )

    assert result == {
        "a": [1, 3],
        2: ["two", "second two"],
    }


def test_zip_dicts_with_non_iterable_argument_raises_type_error():
    with pytest.raises(TypeError):
        zip_dicts({"a": 1}, 123)


def test_zip_dicts_with_iterable_non_mapping_argument_raises_attribute_error():
    with pytest.raises(AttributeError):
        zip_dicts({"a": 1}, ["a"])
